"  await runTest('S2.3', 'Static Require Analysis: Verify 100% core built-in / local module requires', function () {
    const allowedCoreModules = new Set([
      'http', 'https', 'fs', 'path', 'url', 'crypto', 'stream', 'net',
      'child_process', 'module', 'events', 'util', 'os', 'vm', 'buffer',
      'webos-service' // Allowed target webOS system module
    ]);

    const requiredModulesFound = [];
    const disallowedRequires = [];

    for (let f = 0; f < SERVICE_FILES.length; f++) {
      const filename = SERVICE_FILES[f];
      const filePath = path.join(SERVICE_DIR, filename);
      const rawCode = fs.readFileSync(filePath, 'utf8');
      const stripped = stripCommentsAndStrings(rawCode);

      const requireRegex = /\brequire\s*\(\s*['"]([^'"]+)['"]\s*\)/g;
      let match;
      while ((match = requireRegex.exec(stripped)) !== null) {
        const modName = match[1];
        requiredModulesFound.push({ file: filename, module: modName });

        const isRelative = modName.startsWith('./') || modName.startsWith('../');
        const isAllowedCore = allowedCoreModules.has(modName);

        if (!isRelative && !isAllowedCore) {
          disallowedRequires.push({ file: filename, module: modName });
        }
      }
    }

    assert(disallowedRequires.length === 0, 'Disallowed external requires detected: ' + JSON.stringify(disallowedRequires));
    return {
      totalRequiresChecked: requiredModulesFound.length,
      disallowedRequires: 0,
      modules: Array.from(new Set(requiredModulesFound.map(function (r) { return r.module; })))
    };
  });"

